(function(){
  var $=function(id){return document.getElementById(id)};
  function run(){
    var text=$('src').value;
    var found=text.match(/#[\p{L}\p{N}_]+/gu)||[];
    var lower=$('lower').checked;
    var counts={}, order=[], display={};
    found.forEach(function(raw){
      var body=raw.slice(1);
      var key=body.toLowerCase();
      if(!(key in counts)){ counts[key]=0; order.push(key); display[key]= lower?key:body; }
      counts[key]++;
    });
    var keys=order.slice();
    var f=$('filter').value;
    if(f==='rep') keys=keys.filter(function(k){return counts[k]>1});
    if(f==='once') keys=keys.filter(function(k){return counts[k]===1});
    var s=$('sort').value;
    if(s==='freq') keys.sort(function(a,b){ return counts[b]-counts[a] || a.localeCompare(b); });
    if(s==='az') keys.sort(function(a,b){ return a.localeCompare(b); });
    if(s==='len') keys.sort(function(a,b){ return a.length-b.length || a.localeCompare(b); });

    var hash=$('keephash').checked?'#':'';
    var out=keys.map(function(k){ return hash+display[k]; });
    $('out').textContent = out.length ? out.join(' ') : 'Your hashtags appear here';
    $('ntotal').textContent=found.length;
    $('nuniq').textContent=order.length;
    var top=order.slice().sort(function(a,b){return counts[b]-counts[a]})[0];
    $('ntop').textContent= top ? '#'+display[top] : 'none yet';

    var max=Math.max.apply(null,keys.map(function(k){return counts[k]}).concat([1]));
    $('table').innerHTML = keys.length
      ? '<div class="he-row he-head"><span>Hashtag</span><span class="c">Used</span><span></span></div>'+
        keys.slice(0,80).map(function(k){
          return '<div class="he-row"><span class="t">#'+display[k]+'</span>'+
            '<span class="c">'+counts[k]+'</span>'+
            '<span class="he-bar"><i style="width:'+(counts[k]/max*100).toFixed(1)+'%"></i></span></div>';
        }).join('')+
        (keys.length>80?'<div class="he-row"><span class="t">and '+(keys.length-80)+' more, all included when you copy</span></div>':'')
      : '';
    if(window.WT) WT.resize();
  }
  ['src','sort','filter','keephash','lower'].forEach(function(id){
    $(id).addEventListener('input',run); $(id).addEventListener('change',run);
  });
  $('copy').addEventListener('click',function(){
    var ok=WT.copy($('out').textContent);
    this.textContent=ok?'Copied':'Press Ctrl+C';
    var b=this; setTimeout(function(){b.textContent='Copy list'},1400);
  });
  $('copycsv').addEventListener('click',function(){
    var rows=[].slice.call(document.querySelectorAll('.he-row')).slice(1).map(function(r){
      var t=r.querySelector('.t'), c=r.querySelector('.c');
      return t&&c ? t.textContent+'\t'+c.textContent : '';
    }).filter(Boolean).join('\n');
    var ok=WT.copy(rows);
    this.textContent=ok?'Copied':'Press Ctrl+C';
    var b=this; setTimeout(function(){b.textContent='Copy with counts'},1400);
  });
  $('clear').addEventListener('click',function(){ $('src').value=''; run(); });
  run();
})();
